style.css:
/* Neon Pirate – Midnight | Global */
/* i really want this to be global */

/* Change these colours if you want */
:root {
  --my-bg: #080008;
  --my-surface: #130713;
  --my-pink: #FF00A8;
  --my-pink-glow: #ff38c7;
  --my-text: #f5edf4;
  --my-muted: #a99aaa;
}

/* Dark backgrounds */
html,
body {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* Neon links */
a {
  color: var(--my-pink) !important;
}

a:hover {
  color: var(--my-pink-glow) !important;
  text-shadow: 0 0 8px var(--my-pink) !important;
}

/* Buttons */
button,
[role="button"],
input[type="button"],
input[type="submit"] {
  background: var(--my-surface) !important;
  color: var(--my-pink) !important;
  border: 1px solid var(--my-pink) !important;
  border-radius: 8px !important;
}

/* Neon hover */
button:hover,
[role="button"]:hover {
  box-shadow: 0 0 12px var(--my-pink) !important;
}

/* Input fields */
input,
textarea,
select {
  background: #100810 !important;
  color: var(--my-text) !important;
  border: 1px solid #66204f !important;
  border-radius: 8px !important;
}

/* Selection */
::selection {
  background: var(--my-pink) !important;
  color: #000 !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 9px !important;
}

::-webkit-scrollbar-thumb {
  background: var(--my-pink) !important;
  border-radius: 10px !important;
}
